/*
 * A153161  Numerators of Stern-Brocot tree hanging between 1/3 and 2/3;
 *          denominators=A153162.
 * https://oeis.org/A153161
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  frac, nonn, tabf
 * Formula:   a(n) = numerators of Stern‑Brocot fractions between 1/3 and 2/3,
 *            generated by breadth‑first traversal of the subtree with root
 *            1/2. The n‑th term is the numerator of the n‑th node (1‑based)
 * Range:     u8 n <= 82, u16 n <= 82, u32 n <= 82, u64 n <= 82, u128 n <= 82,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdlib.h>

typedef struct {
    seq_t a, b;      /* fraction a/b of the node */
    seq_t aL, bL;    /* left boundary of the node's interval (L) */
    seq_t aR, bR;    /* right boundary of the node's interval (R) */
} Node;

seq_t a(idx_t n)
{
    if (n == 0) return 0;  /* offset is 1; n==0 is undefined, return 0 */

    /* allocate enough space for at most 2n+10 nodes (degree ≤2 per node) */
    size_t cap = 2 * (size_t)n + 10;
    Node *q = (Node *)malloc(cap * sizeof(Node));
    if (!q) return 0;  /* allocation failure */

    size_t front = 0, back = 0;

    /* root node: fraction 1/2 with bounds 1/3 and 2/3 */
    q[back++] = (Node){ .a = 1, .b = 2,
                        .aL = 1, .bL = 3,
                        .aR = 2, .bR = 3 };

    /* Breadth‑first traversal */
    while (front < back) {
        Node cur = q[front++];
        if (front - 1 == (size_t)(n - 1)) {
            seq_t result = cur.a;
            free(q);
            return result;
        }

        /* left child: mediant of left boundary and current node */
        if (back + 2 <= cap) {
            seq_t aL = cur.aL + cur.a;
            seq_t bL = cur.bL + cur.b;
            q[back++] = (Node){ .a = aL, .b = bL,
                                .aL = cur.aL, .bL = cur.bL,
                                .aR = cur.a,  .bR = cur.b };
        }

        /* right child: mediant of current node and right boundary */
        if (back + 1 <= cap) {
            seq_t aR = cur.a + cur.aR;
            seq_t bR = cur.b + cur.bR;
            q[back++] = (Node){ .a = aR, .b = bR,
                                .aL = cur.a,  .bL = cur.b,
                                .aR = cur.aR, .bR = cur.bR };
        }
    }

    /* Should not reach here */
    free(q);
    return 0;
}
